import React from "react";
import { useNavigate } from "react-router-dom";
import JobCard from "./JobCard";

const jobs = [
  {id:1,title:"Frontend Developer",role:"React.js Developer",location:"Bengaluru",experience:"2-4 years",skills:"React, JS, HTML, CSS",description:"Build responsive UI components."},
  {id:2,title:"Backend Engineer",role:"Node.js Developer",location:"Hyderabad",experience:"3-5 years",skills:"Node.js, Express, MongoDB",description:"Develop REST APIs and database operations."},
  {id:3,title:"UI/UX Designer",role:"Product Designer",location:"Chennai",experience:"1-3 years",skills:"Figma, Adobe XD",description:"Design UI and improve UX."},
  {id:4,title:"Full Stack Developer",role:"MERN Developer",location:"Pune",experience:"3-5 years",skills:"MongoDB, Express, React, Node",description:"Build full stack web apps."},
  {id:5,title:"Data Analyst",role:"Business Analyst",location:"Mumbai",experience:"2-4 years",skills:"Excel, SQL, Tableau",description:"Analyze business data and create reports."},
  {id:6,title:"DevOps Engineer",role:"Cloud Engineer",location:"Delhi",experience:"3-6 years",skills:"AWS, Docker, Jenkins",description:"Manage CI/CD pipelines."},
  {id:7,title:"Mobile Developer",role:"Flutter Developer",location:"Bengaluru",experience:"2-4 years",skills:"Flutter, Dart",description:"Build mobile apps for Android/iOS."},
  {id:8,title:"QA Engineer",role:"Automation Tester",location:"Chennai",experience:"2-5 years",skills:"Selenium, Java",description:"Test and automate test cases."},
  {id:9,title:"Marketing Executive",role:"Digital Marketer",location:"Mumbai",experience:"1-3 years",skills:"SEO, Social Media, Ads",description:"Plan and execute marketing campaigns."},
  {id:10,title:"HR Executive",role:"HR Associate",location:"Delhi",experience:"1-3 years",skills:"Recruitment, Payroll, HRMS",description:"Manage recruitment and employee relations."},
];

export default function JobList() {
  const navigate = useNavigate();
  return (
    <div className="job-list-container">
      <h1 style={{textAlign:"center", marginBottom:"30px"}}>Positions Opened</h1>
      {jobs.map(job => <JobCard key={job.id} job={job} onClick={() => navigate(`/job/${job.id}`)} />)}
    </div>
  );
}
